CREATE TABLE IF NOT EXISTS `org_user` (`admin` TINYINT(1) NOT NULL DEFAULT 0, `created_at` BIGINT NOT NULL, `email` VARCHAR(254) NULL, `id` BIGINT NOT NULL AUTO_INCREMENT, `name` VARCHAR(50) NULL, `org_org` BIGINT NOT NULL, `phone` VARCHAR(20) NULL, `position` VARCHAR(50) NULL, `status` ENUM('active', 'disabled') NOT NULL DEFAULT 'active', `updated_at` BIGINT NOT NULL, `user_user` BIGINT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_org_user_membership` (`org_org`, `user_user`), KEY `idx_org_user_user_status_admin` (`user_user`, `status`, `admin`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
